[CmdletBinding()]
param(
    [string]$BuildRoot = 'out/build/win-amd64-relwithdebinfo',
    [string]$GameRoot = 'private/game',
    [Parameter(Mandatory)][ValidatePattern('^[0-9]{8}-[0-9]{6}-[0-9a-f]{8}$')][string]$DigitalEvidenceRun,
    [Parameter(Mandatory)][ValidatePattern('^[0-9]{8}-[0-9]{6}-[0-9a-f]{8}$')][string]$AnalogFocusEvidenceRun
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$repoRoot=(Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..')).Path
$verifier=Join-Path $PSScriptRoot 'verify-controller-matrix.ps1'
$gameVerifier=Join-Path $PSScriptRoot 'verify-game-manifest.ps1'
$toolchainResolver=Join-Path $PSScriptRoot 'Resolve-Toolchain.ps1'
$sdkRoot=Join-Path $repoRoot 'third_party/rexglue-sdk'
$utf8=[Text.UTF8Encoding]::new($false)
$windowPattern='^mcla \[rexglue-v[^\]]+\]$'
$captureMarker='MCLA graphics: nontrivial guest frame captured '
$readyMarker='SDL_CONTROLLER_MATRIX_AUDIT_ARM v=1 phase=title status=READY active_mask=1 neutral=1'
$summaryMarker='SDL_CONTROLLER_MATRIX_AUDIT_SUMMARY v=1 phase=title status=PASS button_sdl_mask=F3FF button_guest_mask=F3FF analog_sdl_mask=3FF analog_guest_mask=3FF focus_lost=1 focus_neutral=1 focus_gained=1 hotplug_removed=1 hotplug_disconnected=1 hotplug_reconnected=1 hotplug_success=1 assigned_mask=1 rumble_pattern_mask=7 rumble_stop_mask=7 digital_source=prior-evidence digital_current_records=0 analog_source=prior-evidence analog_current_records=0 focus_source=prior-evidence focus_current_records=0 rumble_source=prior-evidence rumble_current_records=0 unexpected=0 failures=0 dropped_records=0'
$artifactNames=@('mcla.exe','rexruntimerd.dll','TracyClientrd.dll','rexgpu-xenosrd.dll')

if(-not('MclaXamProfileWindow'-as[type])){Add-Type -TypeDefinition @'
using System; using System.Collections.Generic; using System.Runtime.InteropServices; using System.Text;
public static class MclaXamProfileWindow {
  private delegate bool E(IntPtr h,IntPtr p); [DllImport("user32.dll")] static extern bool EnumWindows(E c,IntPtr p);
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h,out uint p); [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern int GetWindowText(IntPtr h,StringBuilder s,int n); [DllImport("user32.dll")] static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);
  public static IntPtr[] Handles(int pid){var a=new List<IntPtr>();EnumWindows(delegate(IntPtr h,IntPtr x){uint p;GetWindowThreadProcessId(h,out p);if(p==(uint)pid&&IsWindowVisible(h))a.Add(h);return true;},IntPtr.Zero);return a.ToArray();}
  public static string Title(IntPtr h){var s=new StringBuilder(1024);int n=GetWindowText(h,s,s.Capacity);return n>0?s.ToString(0,n):String.Empty;} public static bool Close(IntPtr h){return PostMessage(h,0x10,IntPtr.Zero,IntPtr.Zero);}
}
'@}
function Get-PathInside {param([string]$Path,[string]$Description,[switch]$MustExist)$candidate=if([IO.Path]::IsPathRooted($Path)){$Path}else{Join-Path $repoRoot $Path};$full=[IO.Path]::GetFullPath($candidate);$prefix=$repoRoot.TrimEnd('\')+'\';if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "$Description must stay inside the repository."};$current=$repoRoot;foreach($part in @($full.Substring($prefix.Length).Split('\')|Where-Object{$_.Length})){$current=Join-Path $current $part;if((Test-Path $current)-and((Get-Item $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint)){throw "$Description traverses a reparse point."}};if($MustExist-and-not(Test-Path $full)){throw "$Description is missing."};$full}
function Get-Tree {param([string]$Root)$items=@(Get-ChildItem $Root -Recurse -Force);$entries=@();$files=@($items|Where-Object{-not$_.PSIsContainer}|Sort-Object FullName);foreach($i in @((Get-Item $Root -Force))+$items){if($i.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Tree contains a reparse point.'}};foreach($d in @($items|Where-Object PSIsContainer|Sort-Object FullName)){$entries+=[ordered]@{kind='directory';path=$d.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/')}};foreach($f in $files){$entries+=[ordered]@{kind='file';path=$f.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/');length=$f.Length;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}};$json=ConvertTo-Json -InputObject @($entries) -Depth 4 -Compress;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};$bytes=0L;foreach($f in $files){$bytes+=$f.Length};[pscustomobject]@{Hash=$hash;FileCount=$files.Count;DirectoryCount=@($items|Where-Object PSIsContainer).Count;Bytes=$bytes}}
function Get-Game {param([string]$Root)$t=Get-Tree $Root;$v=&$gameVerifier -GamePath $Root -VerifyHashes;[ordered]@{file_count=$v.FileCount;payload_bytes=$v.PayloadBytes;hashes_verified=$v.HashesVerified;manifest_sha256=(Get-FileHash $v.ManifestPath -Algorithm SHA256).Hash;tree_sha256=$t.Hash;tree_file_count=$t.FileCount;tree_directory_count=$t.DirectoryCount;tree_bytes=$t.Bytes}}
function Get-Artifacts {param([string]$Root)@($artifactNames|ForEach-Object{$p=Get-PathInside(Join-Path $Root $_)"Artifact $_" -MustExist;[ordered]@{name=$_;sha256=(Get-FileHash $p -Algorithm SHA256).Hash}})}
function Get-Targets {param([string]$Exe)@((Get-Process mcla -ErrorAction SilentlyContinue)|Where-Object{try{[string]::Equals($_.Path,$Exe,[StringComparison]::OrdinalIgnoreCase)}catch{$false}})}
function Assert-NoTarget {param([string]$Exe)if(@(Get-Targets $Exe).Count){throw 'Exact canonical MCLA process is already running.'}}
function Test-LogMarkers {param([string]$Current,[string[]]$Markers)$dir=Split-Path -Parent $Current;if(-not(Test-Path $dir)){return $false};$found=@{};foreach($marker in $Markers){$found[$marker]=$false};foreach($file in @(Get-ChildItem $dir -File -Filter 'mcla*.log')){try{$stream=[IO.File]::Open($file.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite);try{$reader=[IO.StreamReader]::new($stream,$utf8,$true,65536,$false);$text=$reader.ReadToEnd();$reader.Dispose()}finally{$stream.Dispose()};foreach($marker in $Markers){if(-not$found[$marker]-and$text.Contains($marker)){$found[$marker]=$true}}}catch{}};foreach($marker in $Markers){if(-not$found[$marker]){return $false}};return $true}
function Close-Window {param([Diagnostics.Process]$Process)$m=@();foreach($h in [MclaXamProfileWindow]::Handles($Process.Id)){if([regex]::IsMatch([MclaXamProfileWindow]::Title($h),$windowPattern)){$m+=$h}};if($m.Count-ne1-or-not[MclaXamProfileWindow]::Close($m[0])){throw 'Exact PID/window WM_CLOSE contract failed.'}}
function Assert-Prior {param([Collections.ArrayList]$Prior)foreach($p in $Prior){if((Get-Tree $p.Root).Hash-ne$p.Hash){throw 'A prior cycle mutated.'}}}
function Wait-MatrixMarker {param([Diagnostics.Process]$Process,[string]$Log,[string[]]$Markers,[string]$Step,[string]$Instruction,[int]$TimeoutSeconds=30)Write-Host ('{0,-22} | {1,-44} | awaiting' -f $Step,$Instruction) -ForegroundColor Yellow;$watch=[Diagnostics.Stopwatch]::StartNew();while($watch.Elapsed.TotalSeconds-lt$TimeoutSeconds){if($Process.HasExited){throw "Process exited during '$Step'."};if(Test-LogMarkers $Log $Markers){Write-Host ('{0,-22} | {1,-44} | PASS' -f $Step,$Instruction) -ForegroundColor Green;return $watch.ElapsedMilliseconds};Start-Sleep -Milliseconds 100};throw "Controller step '$Step' timed out after $TimeoutSeconds seconds."}

Write-Host 'M4-006 [1/7]: validating canonical inputs and source-game integrity...'
$build=Get-PathInside $BuildRoot 'Build root' -MustExist;$game=Get-PathInside $GameRoot 'Game root' -MustExist
if(-not[string]::Equals($build,[IO.Path]::GetFullPath((Join-Path $repoRoot 'out/build/win-amd64-relwithdebinfo')),[StringComparison]::OrdinalIgnoreCase)-or-not[string]::Equals($game,[IO.Path]::GetFullPath((Join-Path $repoRoot 'private/game')),[StringComparison]::OrdinalIgnoreCase)){throw 'M4-006 final gate requires canonical inputs.'}
$digitalBefore=&$verifier -DigitalEvidenceOnly -DigitalEvidenceRun $DigitalEvidenceRun;if($digitalBefore.Classification-cne'digital-pass_gameplay-transition-blocker'-or$digitalBefore.ControlledExitPassed){throw 'Prior digital evidence classification is not acceptable for continuation.'}
$analogFocusBefore=&$verifier -AnalogFocusEvidenceOnly -AnalogFocusEvidenceRun $AnalogFocusEvidenceRun;if($analogFocusBefore.Classification-cne'analog-focus-pass_post-focus-churn-blocker'-or$analogFocusBefore.ControlledExitPassed){throw 'Prior analog/focus evidence classification is not acceptable for hotplug continuation.'}
foreach($p in @($verifier,$gameVerifier,$toolchainResolver,(Join-Path $sdkRoot 'CMakePresets.json'),(Join-Path $game 'default.xex'))){[void](Get-PathInside $p 'Required input' -MustExist)}
$evidence=Get-PathInside 'private/evidence/M4-006' 'Evidence root';[IO.Directory]::CreateDirectory($evidence)|Out-Null;$runRoot=Join-Path $evidence ((Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,8));$runs=Join-Path $runRoot 'runs';[IO.Directory]::CreateDirectory($runs)|Out-Null
$sdkLog=Join-Path $runRoot 'sdk-install.log';$inputTestLog=Join-Path $runRoot 'sdk-input-test.log';$buildLog=Join-Path $runRoot 'relwithdebinfo-clean-build.log';$toolchain=&$toolchainResolver -ExportPath;$cmake=$toolchain.CMakePath;$gameBefore=Get-Game $game
Write-Host 'M4-006 [2/7]: clean-building and installing ReXGlue SDK (this may take several minutes)...'
$timer=[Diagnostics.Stopwatch]::StartNew();Push-Location $sdkRoot;try{&$cmake --preset win-amd64 -DREXGLUE_BUILD_TESTS=ON *>&1|Tee-Object -FilePath $sdkLog|Out-Null;if($LASTEXITCODE-ne0){throw "SDK configure failed with exit $LASTEXITCODE. Private run: '$runRoot'."};&$cmake --build out/build/win-amd64 --config RelWithDebInfo --target install --clean-first --parallel 8 *>&1|Tee-Object -FilePath $sdkLog -Append|Out-Null;if($LASTEXITCODE-ne0){throw "SDK install failed with exit $LASTEXITCODE. Private run: '$runRoot'."};&$cmake --build out/build/win-amd64 --config RelWithDebInfo --target unit_tests --parallel 8 *>&1|Tee-Object -FilePath $sdkLog -Append|Out-Null;$sdkExit=$LASTEXITCODE}finally{Pop-Location};$timer.Stop();if($sdkExit-ne0){throw "SDK install/unit build failed with exit $sdkExit. Private run: '$runRoot'."};$sdkMs=$timer.ElapsedMilliseconds
Write-Host 'M4-006 [3/7]: running focused SDL and RTL compatibility tests...'
$unitExe=Get-PathInside (Join-Path $sdkRoot 'out/win-amd64/RelWithDebInfo/unit_tests.exe') 'SDK focused unit test executable' -MustExist;$timer.Restart();&$unitExe '[input][sdl][controller-matrix],[kernel][rtl][critical-section]' *>&1|Tee-Object -FilePath $inputTestLog|Out-Null;$inputTestExit=$LASTEXITCODE;$timer.Stop();if($inputTestExit-ne0){throw "Focused SDK controller/RTL tests failed with exit $inputTestExit. Private run: '$runRoot'."};$inputTestMs=$timer.ElapsedMilliseconds;$inputTestText=[IO.File]::ReadAllText($inputTestLog);$testMatch=[regex]::Match($inputTestText,'All tests passed \(([0-9]+) assertions in ([0-9]+) test case(?:s)?\)');if(-not$testMatch.Success){throw 'Focused controller/RTL test totals are missing.'};$inputAssertions=[int]$testMatch.Groups[1].Value;$inputCases=[int]$testMatch.Groups[2].Value;if($inputAssertions-ne90-or$inputCases-ne13){throw 'Focused controller/RTL test totals changed.'}
Write-Host 'M4-006 [4/7]: clean-building the MCLA host (output stays in the private build log)...'
$timer.Restart();Push-Location $repoRoot;try{&$cmake --preset win-amd64-relwithdebinfo *>&1|Tee-Object -FilePath $buildLog|Out-Null;if($LASTEXITCODE-ne0){throw "App configure failed with exit $LASTEXITCODE."};&$cmake --build --preset win-amd64-relwithdebinfo --target mcla --clean-first --parallel 8 *>&1|Tee-Object -FilePath $buildLog -Append|Out-Null;$buildExit=$LASTEXITCODE}finally{Pop-Location};$timer.Stop();if($buildExit-ne0){throw "App clean build failed with exit $buildExit. Private run: '$runRoot'."};$buildMs=$timer.ElapsedMilliseconds
$exe=Join-Path $build 'mcla.exe';Assert-NoTarget $exe;$artifactsBefore=Get-Artifacts $build;$root=Join-Path $runs '01';$user=Join-Path $root 'user';$cache=Join-Path $root 'cache';[IO.Directory]::CreateDirectory($user)|Out-Null;[IO.Directory]::CreateDirectory($cache)|Out-Null;$log=Join-Path $root 'mcla.log';$bmp=Join-Path $user 'mcla-first-frame.bmp';$process=$null;$forced=$false
Write-Host 'M4-006 [5/7]: launching the title route; startup normally takes about 45 seconds.'
Write-Host 'M4-006: keep exactly one selected controller connected, A released, and the game window focused.'
try{$capture=[Diagnostics.Stopwatch]::StartNew();$process=Start-Process $exe -ArgumentList @('--sdl_controller_matrix_audit=true','--sdl_controller_matrix_hotplug_resume=true','--input_backend=sdl','--mnk_mode=false','--gpu_render_audit=true','--async_shader_compilation=false','--mcla_first_frame_probe=true','--mcla_first_frame_settle_seconds=35','--render_target_path_d3d12=rtv','--log_max_file_size_mb=5','--log_max_files=15',"--game_data_root=`"$game`"","--user_data_root=`"$user`"","--cache_root=`"$cache`"","--log_file=`"$log`"",'--log_level=trace','--fullscreen=false') -WorkingDirectory $build -PassThru;$resumeMarker='SDL_CONTROLLER_MATRIX_AUDIT_HOTPLUG_RESUME v=1 phase=title status=READY prior_digital=1 prior_rumble=1 prior_analog=1 prior_focus=1 button_sdl_mask=F3FF button_guest_mask=F3FF analog_sdl_mask=3FF analog_guest_mask=3FF rumble_pattern_mask=7 rumble_stop_mask=7 focus_lost=1 focus_neutral=1 focus_gained=1 source_seq=24';$null=Wait-MatrixMarker $process $log @($captureMarker,$readyMarker,$resumeMarker) 'CONTINUATION READY' 'prior digital/rumble/analog/focus bound; begin hotplug only' 60;$capture.Stop();$matrix=[Diagnostics.Stopwatch]::StartNew();Write-Host ('{0,-22} | {1,-44} | {2}' -f 'STEP','ACTION','STATUS') -ForegroundColor Cyan;$stepMs=@()
$null=Wait-MatrixMarker $process $log @('SDL_CONTROLLER_MATRIX_AUDIT_HOTPLUG v=1 event=removed slot=0 seq=') 'DISCONNECT' 'disconnect selected controller';$null=Wait-MatrixMarker $process $log @('SDL_CONTROLLER_MATRIX_AUDIT_HOTPLUG v=1 event=disconnected slot=0 result=0000048F seq=') 'GUEST DISCONNECTED' 'leave disconnected';$null=Wait-MatrixMarker $process $log @('SDL_CONTROLLER_MATRIX_AUDIT_HOTPLUG v=1 event=reconnected slot=0 active_mask=1 seq=') 'RECONNECT' 'reconnect selected controller';$null=Wait-MatrixMarker $process $log @('SDL_CONTROLLER_MATRIX_AUDIT_HOTPLUG v=1 event=success slot=0 result=00000000 seq=',$summaryMarker) 'FINAL SUCCESS' 'keep controller neutral';$matrix.Stop();$dwell=[Diagnostics.Stopwatch]::StartNew();while($dwell.ElapsedMilliseconds-lt2000){Start-Sleep -Milliseconds 50};$dwell.Stop();Close-Window $process;$exit=[Diagnostics.Stopwatch]::StartNew();$signaled=$process.WaitForExit(10000);$exit.Stop();if(-not$signaled-or$process.ExitCode-ne0){throw 'Controlled exit contract failed.'};Assert-NoTarget $exe;$p=&$verifier -ProbeOnly -RuntimeLogPath $log -BmpPath $bmp;$u=Get-Tree $user;$k=Get-Tree $cache}catch{$failure=$_;if($process-and-not$process.HasExited){$forced=$true;Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue;$null=$process.WaitForExit(5000)};if($forced){throw "M4-006 failure required force cleanup. $($failure.Exception.Message) Private run: '$runRoot'."};throw}
Write-Host 'M4-006 [6/7]: rehashing game, artifacts, split evidence...';$t=Get-Tree $root;$gameAfter=Get-Game $game;$artifactsAfter=Get-Artifacts $build;$digitalAfter=&$verifier -DigitalEvidenceOnly -DigitalEvidenceRun $DigitalEvidenceRun;if($digitalAfter.Tree.Hash-cne$digitalBefore.Tree.Hash){throw 'Prior immutable digital evidence changed during continuation.'};$analogFocusAfter=&$verifier -AnalogFocusEvidenceOnly -AnalogFocusEvidenceRun $AnalogFocusEvidenceRun;if($analogFocusAfter.Tree.Hash-cne$analogFocusBefore.Tree.Hash){throw 'Prior immutable analog/focus evidence changed during hotplug continuation.'};$record=[ordered]@{index=1;capture_elapsed_milliseconds=$capture.ElapsedMilliseconds;matrix_elapsed_milliseconds=$matrix.ElapsedMilliseconds;step_count=1;left_deadzone=7849;right_deadzone=8689;trigger_threshold=30;nonzero_rumble_pulses_submitted_to_device=0;rumble_operator_prompted=$false;dwell_elapsed_milliseconds=$dwell.ElapsedMilliseconds;exit_elapsed_milliseconds=$exit.ElapsedMilliseconds;exit_code=0;close_requested=$true;harness_force_cleanup=$false;process_signal_confirmed=$true;process_cleanup_confirmed=$true;runtime_logs=@($p.LogSet.Files);runtime_log_file_count=$p.LogSet.Count;runtime_log_bytes=$p.LogSet.Bytes;runtime_log_set_sha256=$p.LogSet.Hash;capture_relative_path='runs/01/user/mcla-first-frame.bmp';capture_sha256=$p.Title.Bmp.Sha256;capture_bytes=$p.Title.Bmp.Bytes;logo_edge_correlation_ppm=$p.Title.Roi.LogoCorrelationPpm;press_edge_correlation_ppm=$p.Title.Roi.PressCorrelationPpm;resolve_calls=$p.Title.Audit.ResolveCalls;draw_issued=$p.Title.Audit.DrawIssued;rtl_compatibility_markers=$p.RtlCompatibilityCount;audit_resume_count=$p.ResumeCount;audit_input_ready_count=$p.InputReadyCount;audit_button_records=$p.ButtonCount;audit_analog_records=$p.AnalogCount;audit_focus_records=$p.FocusCount;audit_hotplug_records=$p.HotplugCount;audit_rumble_records=$p.RumbleCount;audit_summary_count=1;user_tree_sha256=$u.Hash;cache_tree_sha256=$k.Hash;cycle_tree_sha256=$t.Hash;user_file_count=$u.FileCount;cache_file_count=$k.FileCount;user_bytes=$u.Bytes;cache_bytes=$k.Bytes};$digital=[ordered]@{run_id=$DigitalEvidenceRun;classification=$digitalBefore.Classification;digital_matrix_passed=$true;gameplay_transition_blocked=$true;controlled_exit_passed=$false;title_capture_verified=$true;rumble_command_matrix_passed=$true;rumble_physical_patterns_user_reported='left-right-both';rumble_operator_attestation='external-user-report';rumble_operator_confirmation_recorded_in_run=$false;rumble_attestation_machine_verified=$false;input_ready_verified=$true;fatal_guest_address=$digitalBefore.FatalGuestAddress;immutable_tree_verified=$true;runtime_logs=@($digitalBefore.LogSet.Files);runtime_log_file_count=$digitalBefore.LogSet.Count;runtime_log_bytes=$digitalBefore.LogSet.Bytes;runtime_log_set_sha256=$digitalBefore.LogSet.Hash;capture_relative_path='runs/01/user/mcla-first-frame.bmp';capture_sha256=$digitalBefore.Title.Bmp.Sha256;capture_bytes=$digitalBefore.Title.Bmp.Bytes;capture_width=$digitalBefore.Title.Bmp.Width;capture_height=$digitalBefore.Title.Bmp.Height;audit_button_records=$digitalBefore.ButtonCount;audit_rumble_records=$digitalBefore.RumbleCount;audit_input_ready_count=$digitalBefore.InputReadyCount;fatal_marker_count=$digitalBefore.FatalCount;evidence_tree_sha256=$digitalBefore.Tree.Hash;evidence_file_count=$digitalBefore.Tree.FileCount;evidence_directory_count=$digitalBefore.Tree.DirectoryCount;evidence_bytes=$digitalBefore.Tree.Bytes;cycle_tree_sha256=$digitalBefore.CycleTree.Hash;user_tree_sha256=$digitalBefore.UserTree.Hash;cache_tree_sha256=$digitalBefore.CacheTree.Hash}
$analogFocus=[ordered]@{run_id=$AnalogFocusEvidenceRun;classification=$analogFocusBefore.Classification;analog_matrix_passed=$true;focus_matrix_passed=$true;post_focus_churn_blocked=$true;controlled_exit_passed=$false;title_capture_verified=$true;post_freeze_sdl_remove_unclaimed=$true;immutable_tree_verified=$true;runtime_logs=@($analogFocusBefore.LogSet.Files);runtime_log_file_count=$analogFocusBefore.LogSet.Count;runtime_log_bytes=$analogFocusBefore.LogSet.Bytes;runtime_log_set_sha256=$analogFocusBefore.LogSet.Hash;capture_relative_path='runs/01/user/mcla-first-frame.bmp';capture_sha256=$analogFocusBefore.Title.Bmp.Sha256;capture_bytes=$analogFocusBefore.Title.Bmp.Bytes;capture_width=$analogFocusBefore.Title.Bmp.Width;capture_height=$analogFocusBefore.Title.Bmp.Height;audit_analog_records=$analogFocusBefore.AnalogCount;audit_focus_records=$analogFocusBefore.FocusCount;focus_order_failure_records=$analogFocusBefore.FailureCount;fail_summary_records=$analogFocusBefore.SummaryFailCount;delayed_raw_remove_records=$analogFocusBefore.DelayedRemoveCount;evidence_tree_sha256=$analogFocusBefore.Tree.Hash;evidence_file_count=$analogFocusBefore.Tree.FileCount;evidence_directory_count=$analogFocusBefore.Tree.DirectoryCount;evidence_bytes=$analogFocusBefore.Tree.Bytes;cycle_tree_sha256=$analogFocusBefore.CycleTree.Hash;user_tree_sha256=$analogFocusBefore.UserTree.Hash;cache_tree_sha256=$analogFocusBefore.CacheTree.Hash}
$result=[ordered]@{schema=1;task='M4-006';decision='split-digital-analog-focus-hotplug-matrix';cycle_count=1;capture_timeout_seconds=60;first_frame_settle_seconds=35;step_timeout_seconds=30;post_marker_dwell_milliseconds=2000;exit_timeout_seconds=10;digital_evidence=$digital;analog_focus_evidence=$analogFocus;clean_build=[ordered]@{sdk_install_performed=$true;sdk_install_success=$true;sdk_install_exit_code=0;sdk_install_duration_milliseconds=$sdkMs;sdk_install_log_sha256=(Get-FileHash $sdkLog -Algorithm SHA256).Hash;sdk_input_test_performed=$true;sdk_input_test_success=$true;sdk_input_test_exit_code=0;sdk_input_test_duration_milliseconds=$inputTestMs;sdk_input_test_cases=$inputCases;sdk_input_test_assertions=$inputAssertions;sdk_input_test_log_sha256=(Get-FileHash $inputTestLog -Algorithm SHA256).Hash;sdk_input_test_executable_sha256=(Get-FileHash $unitExe -Algorithm SHA256).Hash;app_clean_build_performed=$true;app_clean_build_success=$true;app_clean_build_exit_code=0;app_clean_build_duration_milliseconds=$buildMs;app_clean_build_log_sha256=(Get-FileHash $buildLog -Algorithm SHA256).Hash;executable_sha256=(Get-FileHash $exe -Algorithm SHA256).Hash};game_identity=[ordered]@{before=$gameBefore;after=$gameAfter};artifacts=[ordered]@{before=$artifactsBefore;after=$artifactsAfter};cycles=@($record);all_write_roots_contained=$true;no_surviving_processes=$true;data_integrity_preserved=$true;title_probe_passed=$true;controller_matrix_probe_passed=$true;operator_interaction_required=$true;multi_pad_physically_claimed=$false;monolithic_physical_run_claimed=$false};$resultPath=Join-Path $runRoot 'result.json';[IO.File]::WriteAllText($resultPath,(($result|ConvertTo-Json -Depth 10)+[Environment]::NewLine),$utf8);Write-Host 'M4-006 [7/7]: running final split-evidence verifier...';$verified=&$verifier -ResultPath $resultPath;[pscustomobject]@{Passed=$verified.Passed;Decision=$verified.Decision;Cycles=$verified.Cycles;DigitalEvidenceRun=$DigitalEvidenceRun;AnalogFocusEvidenceRun=$AnalogFocusEvidenceRun;PrivateRunRoot=$runRoot;ResultPath=$resultPath}
